    "explanation": "1. CONCEPT:\nSimultaneous presence of nitrogen and sulphur in Lassaigne fusion.\n\n2. GIVEN:\nFormation of sodium thiocyanate NaSCN.\n\n3. FORMULA / PRINCIPLE:\nNa + C + N + S -> NaSCN; Fe3+ + SCN- -> [Fe(SCN)]2+ (blood-red thiocyanatoiron(III)).\n\n4. STEP-BY-STEP SOLUTION:\n1. When both nitrogen and sulphur are present in the organic compound, sodium fusion produces sodium thiocyanate (NaSCN) instead of separate NaCN and Na2S.\n2. When acidified with dilute HCl and treated with iron(III) chloride (FeCl3), thiocyanate coordinates with Fe3+ to form the intensely blood-red complex ion [Fe(SCN)]2+ (or Fe(SCN)3).\n3. No Prussian blue is formed unless excess sodium is used to decompose NaSCN into NaCN and Na2S.\n\n5. FINAL ANSWER:\nOption A: Blood red colour due to [Fe(SCN)]2+\n\n6. WHY OTHER OPTIONS ARE WRONG:\nSodium thiocyanate reacts with Fe3+ to produce a characteristic blood-red coloration.",
