    "id": "organic-mcq-424",
    "questionNumber": 424,
    "question": "In Kjeldahl's method, the ammonia evolved from 0.50 g of an organic compound was absorbed in 50 mL of 0.1 M H2SO4. The unreacted acid required 30 mL of 0.1 M NaOH for complete neutralization. The percentage of nitrogen in the compound is:",
    "options": {
      "A": "19.60%",
      "B": "28.00%",
      "C": "14.00%",
      "D": "21.40%"
    },
    "optionsList": [
      "19.60%",
      "28.00%",
      "14.00%",
      "21.40%"
    ],
    "correctAnswer": "A",
    "correctIndex": 0,
    "explanation": "1. CONCEPT:\nKjeldahl back-titration stoichiometry.\n\n2. GIVEN:\nMass = 0.50 g, Initial H2SO4 = 50 mL of 0.1 M (10.0 meq), NaOH = 30 mL of 0.1 M (3.0 meq).\n\n3. FORMULA / PRINCIPLE:\nmeq H2SO4 consumed by NH3 = initial meq acid - meq NaOH used; %N = (1.4 * meq acid consumed) / (mass in grams).\n\n4. STEP-BY-STEP SOLUTION:\n1. Step 1: Calculate total initial milliequivalents of H2SO4: meq = Volume (mL) * Molarity * Basicity = 50 * 0.1 * 2 = 10.0 meq.\n2. Step 2: Milliequivalents of unreacted H2SO4 neutralized by NaOH = 30 * 0.1 * 1 = 3.0 meq.\n3. Step 3: Milliequivalents of H2SO4 neutralized by NH3 = 10.0 - 3.0 = 7.0 meq.\n4. Step 4: % Nitrogen = (1.4 * meq NH3) / mass = (1.4 * 7.0) / 0.50 = 9.8 / 0.50 = 19.60%.\n\n5. FINAL ANSWER:\nOption A: 19.60%\n\n6. WHY OTHER OPTIONS ARE WRONG:\nRemember H2SO4 is dibasic: 50 mL of 0.1 M provides 10 milliequivalents, not 5 milliequivalents.",
    "solutionStructured": {
      "concept": "Kjeldahl back-titration stoichiometry.",
      "given": "Mass = 0.50 g, Initial H2SO4 = 50 mL of 0.1 M (10.0 meq), NaOH = 30 mL of 0.1 M (3.0 meq).",
      "formula": "meq H2SO4 consumed by NH3 = initial meq acid - meq NaOH used; %N = (1.4 * meq acid consumed) / (mass in grams).",
      "stepByStep": "1. Step 1: Calculate total initial milliequivalents of H2SO4: meq = Volume (mL) * Molarity * Basicity = 50 * 0.1 * 2 = 10.0 meq.\n2. Step 2: Milliequivalents of unreacted H2SO4 neutralized by NaOH = 30 * 0.1 * 1 = 3.0 meq.\n3. Step 3: Milliequivalents of H2SO4 neutralized by NH3 = 10.0 - 3.0 = 7.0 meq.\n4. Step 4: % Nitrogen = (1.4 * meq NH3) / mass = (1.4 * 7.0) / 0.50 = 9.8 / 0.50 = 19.60%.",
      "finalAnswer": "Option A: 19.60%",
      "whyOtherOptionsWrong": "Remember H2SO4 is dibasic: 50 mL of 0.1 M provides 10 milliequivalents, not 5 milliequivalents."
    },
