    "explanation": "1. CONCEPT:\nOptical purity and enantiomeric excess calculations.\n\n2. GIVEN:\nObserved rotation = +20.0\u00b0, pure rotation = +50.0\u00b0.\n\n3. FORMULA / PRINCIPLE:\nOptical purity (% ee) = (Observed rotation / Pure rotation) * 100; % Major isomer = ee + (100 - ee)/2.\n\n4. STEP-BY-STEP SOLUTION:\n1. Step 1: Enantiomeric excess (% ee) = (+20.0\u00b0 / +50.0\u00b0) * 100 = 40.0%.\n2. Step 2: A 40% ee means 40% of the mixture is pure (+)-enantiomer, while the remaining 60% is a racemic (1:1) mixture.\n3. Step 3: In the 60% racemic portion, 30% is (+) and 30% is (-).\n4. Step 4: Total percentage of (+)-isomer = 40% + 30% = 70.0%.\n\n5. FINAL ANSWER:\nOption A: 40% ee and 70% (+)-isomer\n\n6. WHY OTHER OPTIONS ARE WRONG:\nThe mixture consists of 70% (+) and 30% (-), giving an excess of 70 - 30 = 40% ee.",
