    "explanation": "1. CONCEPT:\nVector cancellation of bond dipole moments in symmetrical alkenes.\n\n2. GIVEN:\ntrans-1,2-Dichloroethene vs cis-isomer.\n\n3. FORMULA / PRINCIPLE:\nC2h molecular symmetry with center of inversion cancels individual C-Cl and C-H bond dipoles.\n\n4. STEP-BY-STEP SOLUTION:\n1. In trans-1,2-dichloroethene, the two polar C-Cl bonds point in exactly opposite directions in the plane of the molecule (180\u00b0 apart).\n2. Similarly, the two C-H bond dipoles point in equal and opposite directions.\n3. Vector addition of all bond dipoles yields a net molecular dipole moment mu = 0 Debye.\n4. In cis-1,2-dichloroethene, both C-Cl dipoles point toward the same side, reinforcing each other to give a large net dipole moment (mu = 1.90 D).\n\n5. FINAL ANSWER:\nOption A: trans-1,2-Dichloroethene\n\n6. WHY OTHER OPTIONS ARE WRONG:\nThe center of inversion in the trans isomer results in complete vector cancellation.",
